def g(x):
    p = {0: 9, 1: 23, 2: -5}
    return 4 * x + p[x % 3]

# Verification of given values
print(f"g(0) = {g(0)}")
print(f"g(1) = {g(1)}")
print(f"g(2) = {g(2)}")
print(f"g(10) = {g(10)}")

# Verification of the functional equation:
# g(a + g(a) + b) - g(a+b) = g(a-b) - g(a-g(a)-b)
for a in range(-10, 11):
    for b in range(-10, 11):
        lhs = g(a + g(a) + b) - g(a + b)
        rhs = g(a - b) - g(a - g(a) - b)
        if lhs != rhs:
            print(f"Error at a={a}, b={b}: lhs={lhs}, rhs={rhs}")
            break
else:
    print("Functional equation holds for all a, b in [-10, 10].")

print(f"g(2025) = {g(2025)}")

def g_func(x, A, p):
    return A * x + p[x % 3]

A = 4
p = [9, 23, -5]

def check_all():
    for a in range(-10, 11):
        for b in range(-10, 11):
            ga = g_func(a, A, p)
            lhs = g_func(a + ga + b, A, p) - g_func(a + b, A, p)
            rhs = g_func(a - b, A, p) - g_func(a - ga - b, A, p)
            if lhs != rhs:
                return False, a, b, lhs, rhs
    return True, None, None, None, None

success, a, b, lhs, rhs = check_all()
print(f"Success: {success}")
if not success:
    print(f"Failed at a={a}, b={b}, LHS={lhs}, RHS={rhs}")

# Calculate g(2025)
print(f"g(2025) = {g_func(2025, A, p)}")

